// Extracted from the original single-file game. Shared game state is passed explicitly.
export function createControls(ctx) {
function look(dx,dy){ctx.yaw-=dx*.003;ctx.pitch=Math.max(-1.43,Math.min(1.43,ctx.pitch-dy*.003))}ctx.renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){if(document.pointerLockElement!==ctx.renderer.domElement)ctx.renderer.domElement.requestPointerLock?.();ctx.chop()}else{ctx.drag={id:e.pointerId,x:e.clientX,y:e.clientY};ctx.renderer.domElement.setPointerCapture(e.pointerId)}});ctx.renderer.domElement.addEventListener('pointermove',e=>{if(ctx.drag?.id===e.pointerId){look(e.clientX-ctx.drag.x,e.clientY-ctx.drag.y);ctx.drag.x=e.clientX;ctx.drag.y=e.clientY}});ctx.renderer.domElement.addEventListener('pointerup',e=>{if(ctx.drag?.id===e.pointerId)ctx.drag=null});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===ctx.renderer.domElement)look(e.movementX,e.movementY)});
const isTypingTarget=el=>el instanceof Element&&!!el.closest('input, textarea, select, [contenteditable="true"], [role="textbox"]');document.addEventListener('focusin',e=>{if(isTypingTarget(e.target)){for(const code in ctx.keys)ctx.keys[code]=false}});document.addEventListener('keydown',e=>{if(isTypingTarget(e.target)||isTypingTarget(document.activeElement))return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)ctx.requestJump();return}if(e.code==='KeyV'){ctx.toggleView();return}if(e.code==='KeyB'){ctx.setMode(!ctx.buildMode);return}if(e.code==='KeyR'&&ctx.buildMode){ctx.orientation=1-ctx.orientation;return}if(e.code==='KeyE'&&ctx.buildMode){ctx.placeLog();return}if(e.code==='KeyQ'&&ctx.buildMode){ctx.removeLog();return}if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight'].includes(e.code)){ctx.keys[e.code]=true;e.preventDefault()}});document.addEventListener('keyup',e=>{ctx.keys[e.code]=false});window.addEventListener('blur',()=>{for(const code in ctx.keys)ctx.keys[code]=false});ctx.$('jump').addEventListener('pointerdown',e=>{e.preventDefault();ctx.requestJump()});ctx.$('hit').addEventListener('pointerdown',e=>{e.preventDefault();ctx.chop()});const stick=ctx.$('stick'),knob=ctx.$('knob');let joyId=null;function joy(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.max(1,Math.hypot(dx,dy)),factor=Math.min(1,48/len);ctx.joyX=dx*factor/48;ctx.joyY=dy*factor/48;knob.style.transform=`translate(${ctx.joyX*40}px,${ctx.joyY*40}px)`}stick.addEventListener('pointerdown',e=>{e.preventDefault();joyId=e.pointerId;stick.setPointerCapture(e.pointerId);joy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===joyId)joy(e)});function stopJoy(){joyId=null;ctx.joyX=ctx.joyY=0;knob.style.transform='translate(0,0)'}stick.addEventListener('pointerup',stopJoy);stick.addEventListener('pointercancel',stopJoy);
ctx.$('reset').onclick=()=>{if(ctx.isOnline()){alert('В сетевой игре мир общий и сохраняется на сервере.');return;}for(const t of ctx.trees.values())ctx.scene.remove(t);for(const g of ctx.chunks.values())ctx.scene.remove(g);for(const f of ctx.falling)ctx.scene.remove(f.tree);for(const p of ctx.particles)ctx.scene.remove(p.mesh);for(const p of ctx.placed)ctx.scene.remove(p.mesh);ctx.placed.length=0;if(ctx.preview){ctx.scene.remove(ctx.preview);ctx.preview=null}ctx.trees.clear();ctx.chunks.clear();ctx.falling.length=0;ctx.particles.length=0;ctx.felled.clear();ctx.seed=(Math.random()*999999)|0;ctx.px=ctx.pz=ctx.yaw=ctx.pitch=ctx.wood=ctx.cuts=0;ctx.feetY=ctx.verticalSpeed=0;ctx.onGround=true;ctx.$('wood').textContent='0';ctx.$('cut').textContent='0';ctx.updateChunks()};addEventListener('resize',()=>{ctx.camera.aspect=innerWidth/innerHeight;ctx.camera.updateProjectionMatrix();ctx.renderer.setSize(innerWidth,innerHeight)});if(matchMedia('(pointer:coarse)').matches)ctx.$('instructions').innerHTML='Джойстик — ходить · ⬆️ прыжок<br>Свайп — обзор<br>Строительство — справа<br>👤 — сменить камеру';else ctx.$('instructions').innerHTML='WASD — ходить · Shift — бег · Space — прыжок<br>Мышь — обзор<br>B — стройка · E — положить<br>R — повернуть · Q — убрать<br>V — сменить камеру';ctx.loading.remove();ctx.updateChunks();

return {look};
}
